const AUTO_HEADER = `// AUTO-GENERATED BY create-fullstack-feature
// DO NOT EDIT MANUALLY`;

/**
 * Vite has no framework-specific feature files: the module produced by
 * planReactModuleFiles is framework-agnostic and routing is wired through the
 * generated route registry instead.
 *
 * @param {object} _config
 * @returns {{ relativePath: string, contents: string, writeMode?: string }[]}
 */
export function planViteFeatureFiles(_config) {
  return [];
}

/**
 * Idempotently register a feature's pages in Client/src/app/router/generated-routes.tsx.
 * @param {object} config
 * @param {string} [existingContents]
 * @returns {string}
 */
export function buildViteRouteRegistryUpdate(config, existingContents) {
  const {
    singularName: Singular,
    pluralName: Plural,
    kebabPluralName: kebabPlural,
  } = config.feature;
  const ops = config.operations;
  const surface = config.surface ?? { dashboard: true, public: false };

  let content =
    existingContents && existingContents.trim().length > 0
      ? existingContents
      : defaultRegistry();

  content = ensureImport(
    content,
    `import ${Plural}Page from "@/modules/${kebabPlural}/pages/${Plural}Page";`,
  );
  if (ops.create) {
    content = ensureImport(
      content,
      `import Create${Singular}Page from "@/modules/${kebabPlural}/pages/Create${Singular}Page";`,
    );
  }
  if (ops.update) {
    content = ensureImport(
      content,
      `import Edit${Singular}Page from "@/modules/${kebabPlural}/pages/Edit${Singular}Page";`,
    );
  }

  if (surface.dashboard) {
    content = ensureRouteInArray(
      content,
      'generatedDashboardRoutes',
      `  { path: "/dashboard/${kebabPlural}", element: <${Plural}Page /> },`,
    );
    if (ops.create) {
      content = ensureRouteInArray(
        content,
        'generatedDashboardRoutes',
        `  { path: "/dashboard/${kebabPlural}/create", element: <Create${Singular}Page /> },`,
      );
    }
    if (ops.update) {
      content = ensureRouteInArray(
        content,
        'generatedDashboardRoutes',
        `  { path: "/dashboard/${kebabPlural}/:id/edit", element: <Edit${Singular}Page /> },`,
      );
    }
  }

  if (surface.public) {
    content = ensureRouteInArray(
      content,
      'generatedWebsiteRoutes',
      `  { path: "/${kebabPlural}", element: <${Plural}Page /> },`,
    );
  }

  return content;
}

/**
 * @returns {string}
 */
function defaultRegistry() {
  return `${AUTO_HEADER}

import type { RouteObject } from "react-router-dom";

export const generatedWebsiteRoutes: RouteObject[] = [];

export const generatedDashboardRoutes: RouteObject[] = [];
`;
}

/**
 * @param {string} content
 * @param {string} importLine
 */
function ensureImport(content, importLine) {
  if (content.includes(importLine)) {
    return content;
  }

  const lines = content.split('\n');
  let lastImport = -1;
  for (let index = 0; index < lines.length; index += 1) {
    if (/^import\s/.test(lines[index])) {
      lastImport = index;
    }
  }

  if (lastImport === -1) {
    return `${importLine}\n${content}`;
  }

  lines.splice(lastImport + 1, 0, importLine);
  return lines.join('\n');
}

/**
 * @param {string} content
 * @param {string} arrayName
 * @param {string} entryLine
 */
function ensureRouteInArray(content, arrayName, entryLine) {
  if (content.includes(entryLine.trim())) {
    return content;
  }

  const emptyPattern = new RegExp(
    `export const ${arrayName}: RouteObject\\[\\] = \\[\\];`,
  );
  if (emptyPattern.test(content)) {
    return content.replace(
      emptyPattern,
      `export const ${arrayName}: RouteObject[] = [\n${entryLine}\n];`,
    );
  }

  const filledPattern = new RegExp(
    `(export const ${arrayName}: RouteObject\\[\\] = \\[)([\\s\\S]*?)(\\n\\];)`,
  );
  return content.replace(filledPattern, (match, open, inner, close) => {
    const body = inner.replace(/\s+$/, '');
    return `${open}${body}\n${entryLine}${close}`;
  });
}
